import * as T from 'three';
const y=new T.Vector3(0,1,0),x=new T.Vector3(1,0,0),unit=new T.Vector3(1,1,1);
export function buildVehicleWheels(group,p,own){if(!p.showWheels)return;const geometry=new T.CylinderGeometry(1,1,1,16,1),tire=new T.MeshStandardMaterial({color:0x25292e,roughness:.94}),rim=new T.MeshStandardMaterial({color:0x99a3ad,metalness:.7,roughness:.34});geometry.rotateZ(Math.PI/2);for(const resource of [geometry,tire,rim])own(group,resource);group.userData.vehicleWheels=p.wheels.map(w=>{const root=new T.Group(),mesh=new T.Mesh(geometry,tire),hub=new T.Mesh(geometry,rim);mesh.scale.set(w.width,w.radius,w.radius);hub.scale.set(w.width+.006,w.radius*.48,w.radius*.48);root.add(mesh,hub);root.matrixAutoUpdate=false;root.userData.vehicleWheel=true;group.add(root);return root;});group.userData.vehicleProperties=p;}
export function updateVehicleWheels(group,running){const roots=group.userData.vehicleWheels;if(!roots)return;const p=group.userData.vehicleProperties,state=running?group.userData.vehicleFrame:null,position=new T.Vector3(),rotation=new T.Quaternion(),scale=new T.Vector3();group.matrixWorld.decompose(position,rotation,scale);const inverse=group.matrixWorld.clone().invert();for(const [i,root]of roots.entries()){const w=state?.wheels[i]||{...p.wheels[i],suspension:p.wheels[i].restLength,rotation:0,steering:p.wheels[i].steer*p.steering*p.maxSteerAngle*Math.PI/180},center=new T.Vector3(...w.position).addScaledVector(y,-w.suspension).applyQuaternion(rotation).add(position),q=rotation.clone().multiply(new T.Quaternion().setFromAxisAngle(y,w.steering)).multiply(new T.Quaternion().setFromAxisAngle(x,-w.rotation));root.matrix.multiplyMatrices(inverse,new T.Matrix4().compose(center,q,unit));root.updateMatrixWorld(true);}group.userData.vehicleVisual={wheelCount:roots.length,contacts:state?.wheels.filter(w=>w.contact).length||0,speed:state?.speed||0,centers:roots.map(w=>w.getWorldPosition(new T.Vector3()).toArray())};}
